    const outcome = await outcomeOf(orchestrator.processMessage(createSession('weather in Oslo?')));

    expect({
      outcome,
      executorInputs,
      rejectionSeenByProvider: requests[1]?.messages?.at(-1),
    }).toEqual({
      outcome: 'sunny in Oslo',
      executorInputs: [{location: 'Oslo'}],
      rejectionSeenByProvider: {
        role: 'user',
        content: [{type: 'tool_result', toolUseId: 'call-1', content: expect.stringContaining('location')}],
      },
    });
  });
});

